import subprocess, sys, json, os
Y="/workspace/executable"
def run(args, stdin="", cwd="/tmp/evm", env=None):
    e=dict(os.environ); e["TERM"]="dumb"; e.pop("YQ_COLORS",None)
    if env: e.update(env)
    p=subprocess.run([Y]+args, input=stdin.encode(), stdout=subprocess.PIPE, stderr=subprocess.PIPE, cwd=cwd, env=e, timeout=20)
    return p.returncode, p.stdout.decode(), p.stderr.decode()
def show(args, stdin="", env=None, label=None):
    rc,o,er=run(args,stdin,env=env)
